PRAGMA foreign_keys=ON;
BEGIN;
CREATE TABLE IF NOT EXISTS research_runs(run_id TEXT PRIMARY KEY, seed INTEGER NOT NULL,record_count INTEGER NOT NULL CHECK(record_count=50000),dataset_hash TEXT NOT NULL,oracle_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_appointments(
 appointment_id TEXT PRIMARY KEY REFERENCES appointments(appointment_id),run_id TEXT NOT NULL REFERENCES research_runs(run_id),index_at TEXT NOT NULL,survey_at TEXT,
 age INTEGER NOT NULL CHECK(age BETWEEN 18 AND 90),distance_km REAL NOT NULL CHECK(distance_km>=0),lead_days INTEGER NOT NULL CHECK(lead_days>=2),prior_appointments INTEGER NOT NULL CHECK(prior_appointments>=0),prior_no_shows INTEGER NOT NULL CHECK(prior_no_shows BETWEEN 0 AND prior_appointments),prior_cancellations INTEGER NOT NULL CHECK(prior_cancellations BETWEEN 0 AND prior_appointments),prior_no_show_rate REAL NOT NULL CHECK(prior_no_show_rate BETWEEN 0 AND 1),appointment_hour INTEGER NOT NULL CHECK(appointment_hour BETWEEN 0 AND 23),weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),month INTEGER NOT NULL CHECK(month BETWEEN 1 AND 12),vehicle_available INTEGER NOT NULL CHECK(vehicle_available IN (0,1)),area_deprivation_proxy INTEGER NOT NULL CHECK(area_deprivation_proxy BETWEEN 1 AND 5),employment TEXT NOT NULL,preferred_channel TEXT NOT NULL,survey_responded INTEGER NOT NULL CHECK(survey_responded IN (0,1)),active_at_index INTEGER NOT NULL CHECK(active_at_index IN (0,1)),treatment TEXT NOT NULL CHECK(treatment IN ('usual_care','reminder_offer','transport_offer','scheduling_offer','not_applicable')),no_show INTEGER CHECK(no_show IN (0,1)),split TEXT NOT NULL CHECK(split IN ('train','validation','test')),
 CHECK((active_at_index=1 AND no_show IS NOT NULL AND treatment<>'not_applicable') OR (active_at_index=0 AND no_show IS NULL AND treatment='not_applicable')),
 CHECK((survey_responded=0 AND survey_at IS NULL) OR (survey_responded=1 AND survey_at IS NOT NULL AND survey_at<index_at)));
CREATE TABLE IF NOT EXISTS research_oracle(appointment_id TEXT PRIMARY KEY REFERENCES research_appointments(appointment_id),p_usual_care REAL CHECK(p_usual_care BETWEEN 0 AND 1),p_reminder_offer REAL CHECK(p_reminder_offer BETWEEN 0 AND 1),p_transport_offer REAL CHECK(p_transport_offer BETWEEN 0 AND 1),p_scheduling_offer REAL CHECK(p_scheduling_offer BETWEEN 0 AND 1),propensity_usual_care REAL CHECK(propensity_usual_care BETWEEN 0 AND 1),propensity_reminder_offer REAL CHECK(propensity_reminder_offer BETWEEN 0 AND 1),propensity_transport_offer REAL CHECK(propensity_transport_offer BETWEEN 0 AND 1),propensity_scheduling_offer REAL CHECK(propensity_scheduling_offer BETWEEN 0 AND 1));
CREATE INDEX IF NOT EXISTS idx_research_split ON research_appointments(split,active_at_index,index_at);
COMMIT;
